<script setup>import AppShell from'../../Layouts/AppShell.vue';import StateCard from'../../Components/StateCard.vue';import{Head,Link}from'@inertiajs/vue3';defineProps({events:Array})</script><template><AppShell><Head title="Events"/><div class="flex items-end justify-between"><div><p class="eyebrow">Events</p><h1 class="mt-2 font-display text-3xl font-bold">All galleries</h1></div><Link href="/groups/create" class="btn-primary">Create event</Link></div><StateCard v-if="!events.length" class="mt-8" title="Your first story starts here" message="Create an event, invite participants and begin uploading photographs."><Link href="/groups/create" class="btn-primary mt-5">Create event</Link></StateCard><div v-else class="mt-8 grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><Link v-for="e in events" :key="e.id" :href="`/groups/${e.id}`" class="panel overflow-hidden"><div class="h-40 bg-gradient-to-tr from-ink to-indigo"></div><div class="p-5"><h2 class="font-display text-lg font-bold">{{e.name}}</h2><p class="mt-2 text-sm text-black/45">{{e.event_type||'Event'}} · {{e.photos_count}} photographs</p></div></Link></div></AppShell></template>
